// the worst key job you've ever seen

// color which needs to be keyed, 0-255
#define BASE_COLOR vec3(13, 163, 38)

// upper sensitivity -- how high should the opacity be to appear opaque?
#define SENSITIVITY 0.34

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    vec3 color = texture(iChannel0, uv).rgb;
    vec3 color2 = texture(iChannel1, uv).rgb;

    // the difference between the keyed color and the color of the pixel
    // is used directly as opacity for mixing the layers.
    float alpha = length(color2 - (BASE_COLOR / 255.));
    if (alpha > SENSITIVITY)
        alpha = 1.;

    fragColor = vec4(mix(color, color2, alpha), 1);
}
